import { Image, type ImageProps } from 'expo-image';

export type AppImageProps = ImageProps;

/**
 * App-wide image with sensible caching defaults: cached to memory + disk and a
 * short cross-fade in. Import this instead of `expo-image` directly so the cache
 * policy lives in one place. Pass `recyclingKey` (e.g. the item id) in lists so
 * recycled rows don't show a previous image for a frame.
 */
export function AppImage({
  cachePolicy = 'memory-disk',
  transition = 200,
  ...props
}: AppImageProps) {
  return <Image cachePolicy={cachePolicy} transition={transition} {...props} />;
}
